// === Tab: mySketch ===
let colors = ["#c3421a","#dfb405","#4f6abf","#539083","#141318"];

let border = 0;

imax = 5;

function setup() {
	createCanvas(1000,1000);
		colorMode(HSB, 360, 100, 100, 100);
	ellipseMode(CENTER);
	rectMode(CENTER);
	background(85);
	//noLoop();
}

function draw() {

	if (frameCount > imax)
	{
		noLoop();
	}

	noStroke();

	addBlur();

	//strokeWeight(0.5);

	let mySize = map(frameCount,0,imax,150,50);

	for(let x = 200;x < width;x+=300)
	{
		for(let y = 200;y < height;y+=300)
		{

			if (random(0,1) > 0.5)
			{
				drawCircle(x,y,mySize*0.75);	
			}else
			{
				drawTriangle(x,y,mySize*1.75);
			}

			drawRectangle(x,y,mySize/3);
		}

	}
}

function drawCircle(x,y,mySize)
{          
	circle(x,y,mySize);
}


function drawRectangle(x,y,mySize)
{
	fill(generateColor());
	push();
	translate(x,y);
	rotate(random(0,2*PI));
	rect(randomGaussian()*30,randomGaussian()*30,mySize,mySize*3);
	pop();
}

function drawTriangle(x,y,mySize)
{
	fill(generateColor());
	push();
	translate(x,y);
	rotate(random(0,2*PI));
	triangle(-mySize/2,-mySize/4,mySize/2,-mySize/2,-mySize/4,mySize/4);
	pop();
}

function generateColor() {
	return color(colors[floor(random(0, colors.length))]);
}

function addBlur() {
	drawingContext.shadowOffsetX = -2;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = 1;
	drawingContext.shadowColor = 'black';
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
